mapper.select:
SELECT DISTINCT ON (resource_type,resource_id)
       resource_type,resource_id,revision,status,content_hash,etag,created_at,updated_at,published_at
  FROM nw_open_platform_resource_revisions
 WHERE tenant_id=#{tenant}
   AND resource_type=#{type}
   AND status=#{status}
 ORDER BY resource_type,resource_id,revision DESC
 LIMIT #{limit}
